    for (i = 0; i < 3; i++) { var x = parseInt(pa.n[i], 10) || 0, y = parseInt(pb.n[i], 10) || 0; if (x !== y) return x > y ? 1 : -1; }
    if (!pa.pre || !pb.pre) return pa.pre ? -1 : pb.pre ? 1 : 0;
